// Base CSV parser interface and utilities for credit card and bank transaction parsing

import type { ParsedTransaction, CSVParseResult } from '$lib/models/Transaction';

/**
 * Base interface for all CSV parsers
 */
export interface ICSVParser {
	/**
	 * Parse a CSV string and return transactions
	 * @param csvContent The raw CSV file content as a string
	 * @returns CSVParseResult with parsed transactions and any errors
	 */
	parse(csvContent: string): CSVParseResult;

	/**
	 * Validate if the CSV format matches this parser's expected format
	 * @param csvContent The raw CSV file content as a string
	 * @returns true if the format matches, false otherwise
	 */
	validateFormat(csvContent: string): boolean;
}

/**
 * Resolved column layout for a parser.
 *
 * The Template Method only needs to know where the data rows start; each parser
 * extends this with whatever column indices its `parseRow` hook consumes.
 */
export interface CSVLayout {
	/** First row index (0-based) that holds transaction data, not headers. */
	dataStartIndex: number;
}

/**
 * Base CSV parser with a shared `parse()` Template Method and common utilities.
 *
 * `parse()` owns the orchestration every bank parser used to duplicate:
 * strip BOM → `parseCSV` → empty-file guard → resolve the column layout →
 * loop the data rows → collect transactions and errors, all wrapped in a single
 * `try/catch`. Subclasses supply only what varies via two hooks:
 * `resolveLayout()` (header detection + column matching) and `parseRow()` (how a
 * single row maps to a `ParsedTransaction`). See RF-01 in the refactoring backlog.
 */
export abstract class BaseCSVParser<TLayout extends CSVLayout = CSVLayout> implements ICSVParser {
	/**
	 * Minimum number of rows required before parsing is attempted. Most banks ship
	 * a header row plus data (2). TD Bank has no header row (1). Wealth Simple
	 * treats a header-only file as an empty-but-valid result, so it disables the
	 * guard (0).
	 */
	protected minimumRowCount = 2;

	/**
	 * Per-bank sign convention (RF-11).
	 *
	 * The app convention is negative = expense, positive = refund/credit. Most
	 * banks (PC Financial, EQ Bank, RBC, TD, Simplii) already export expenses as
	 * negative, so the default is `false` (keep signs as-is). American Express
	 * exports expenses as positive, so `AmexParser` overrides this to `true` and
	 * `normalizeAmount` inverts the sign. Wealth Simple bypasses `normalizeAmount`
	 * entirely and derives the sign from its `type` column.
	 */
	protected readonly expensesArePositive: boolean = false;

	/**
	 * Template Method: the single, shared parse pipeline for every bank parser.
	 */
	parse(csvContent: string): CSVParseResult {
		const transactions: ParsedTransaction[] = [];
		const errors: string[] = [];

		try {
			const rows = this.parseCSV(this.removeBOM(csvContent));

			if (rows.length < this.minimumRowCount) {
				errors.push('CSV file is empty or has no data rows');
				return { transactions, errors };
			}

			// Hook: locate the header / column indices. On failure the subclass
			// pushes its own format error and returns null.
			const layout = this.resolveLayout(rows, errors, csvContent);
			if (!layout) {
				return { transactions, errors };
			}

			// Hook: map each data row to a transaction (or null to skip / on error).
			for (let i = layout.dataStartIndex; i < rows.length; i++) {
				const transaction = this.parseRow(rows[i], layout, i, errors);
				if (transaction) {
					transactions.push(transaction);
				}
			}
		} catch (e: unknown) {
			errors.push(`Failed to parse CSV: ${e instanceof Error ? e.message : 'Unknown error'}`);
		}

		return { transactions, errors };
	}

	abstract validateFormat(csvContent: string): boolean;

	/**
	 * Hook: detect the header and resolve the column indices this parser needs.
	 *
	 * Return the layout on success, or `null` after pushing a format/column error
	 * onto `errors`. The original (pre-BOM-strip) `csvContent` is provided for
	 * parsers whose `validateFormat` re-parses the raw string.
	 */
	protected abstract resolveLayout(
		rows: string[][],
		errors: string[],
		csvContent: string
	): TLayout | null;

	/**
	 * Hook: map a single data row to a transaction.
	 *
	 * Return `null` to skip the row silently (incomplete/empty) or after pushing a
	 * per-row error. `rowIndex` is 0-based; user-facing messages use `rowIndex + 1`.
	 */
	protected abstract parseRow(
		row: string[],
		layout: TLayout,
		rowIndex: number,
		errors: string[]
	): ParsedTransaction | null;

	/**
	 * Shared row finaliser for parsers whose amount lives in a single value.
	 *
	 * Validates the vendor name, applies the per-bank sign convention via
	 * `normalizeAmount`, and returns the finished transaction. Consolidating the
	 * `normalizeAmount` → assignment step here is what lets `amount` land as a
	 * plain `number` (RF-01): callers have already rejected a null raw amount, and
	 * the guard below narrows `normalizeAmount`'s `number | null` result.
	 *
	 * The per-bank sign convention comes from the `expensesArePositive` subclass
	 * property, applied inside `normalizeAmount`.
	 *
	 * @param rawAmount - Parsed, non-null amount (caller reports invalid amounts).
	 */
	protected finalizeRow(
		transactionDate: string,
		vendorName: string,
		rawAmount: number,
		rowNumber: number,
		errors: string[],
		missingVendorMessage = 'Missing vendor name/description'
	): ParsedTransaction | null {
		if (!vendorName) {
			errors.push(`Row ${rowNumber}: ${missingVendorMessage}`);
			return null;
		}

		const amount = this.normalizeAmount(rawAmount);
		if (amount === null) return null;

		return { transaction_date: transactionDate, vendor_name: vendorName, amount };
	}

	/**
	 * Parse CSV string into rows and columns
	 * Handles quoted fields with commas
	 */
	protected parseCSV(csvContent: string): string[][] {
		const lines = csvContent.split(/\r?\n/);
		const result: string[][] = [];

		// Strip a surviving surrounding "..." pair from a finalized field.
		// EQ Bank exports double-encoded values like `"""-$33.00"""`, which the
		// standard unwrap above reduces to `"-$33.00"` (literal " still present).
		const stripOuterQuotes = (field: string): string => {
			const trimmed = field.trim();
			if (trimmed.length >= 2 && trimmed.startsWith('"') && trimmed.endsWith('"')) {
				return trimmed.slice(1, -1).trim();
			}
			return trimmed;
		};

		for (const line of lines) {
			if (!line.trim()) continue;

			const row: string[] = [];
			let currentField = '';
			let inQuotes = false;

			for (let i = 0; i < line.length; i++) {
				const char = line[i];

				if (char === '"') {
					// Handle escaped quotes
					if (inQuotes && line[i + 1] === '"') {
						currentField += '"';
						i++; // Skip next quote
					} else {
						inQuotes = !inQuotes;
					}
				} else if (char === ',' && !inQuotes) {
					row.push(stripOuterQuotes(currentField));
					currentField = '';
				} else {
					currentField += char;
				}
			}

			// Add the last field
			row.push(stripOuterQuotes(currentField));
			result.push(row);
		}

		return result;
	}

	/**
	 * Parse a date string in MM/DD/YYYY or YYYY-MM-DD format to YYYY-MM-DD
	 */
	protected parseDate(dateStr: string): string | null {
		try {
			// Remove any leading/trailing whitespace
			dateStr = dateStr.trim();

			// Try YYYY-MM-DD format (new EQ Bank format)
			const ymdMatch = dateStr.match(/^(\d{4})-(\d{1,2})-(\d{1,2})$/);
			if (ymdMatch) {
				const [, year, month, day] = ymdMatch;
				return `${year}-${month.padStart(2, '0')}-${day.padStart(2, '0')}`;
			}

			// Try MM/DD/YYYY format
			const mdyMatch = dateStr.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);
			if (mdyMatch) {
				const [, month, day, year] = mdyMatch;
				return `${year}-${month.padStart(2, '0')}-${day.padStart(2, '0')}`;
			}

			// Try DD MMM YYYY format (e.g., "31 May 2025" or "31-May-25")
			const dmmyMatch = dateStr.match(/^(\d{1,2})[\s-]([A-Za-z]{3})[.\s-]*(\d{2,4})$/);
			if (dmmyMatch) {
				const [, day, monthStr, year] = dmmyMatch;
				const monthMap: Record<string, string> = {
					jan: '01',
					feb: '02',
					mar: '03',
					apr: '04',
					may: '05',
					jun: '06',
					jul: '07',
					aug: '08',
					sep: '09',
					oct: '10',
					nov: '11',
					dec: '12'
				};
				const month = monthMap[monthStr.toLowerCase()];
				if (month) {
					const fullYear = year.length === 2 ? `20${year}` : year;
					return `${fullYear}-${month}-${day.padStart(2, '0')}`;
				}
			}

			// Try DD Mon YYYY format with full month name
			const dmonyMatch = dateStr.match(/^(\d{1,2})\s+([A-Za-z]+)\s+(\d{4})$/);
			if (dmonyMatch) {
				const [, day, monthStr, year] = dmonyMatch;
				const monthMap: Record<string, string> = {
					january: '01',
					february: '02',
					march: '03',
					april: '04',
					may: '05',
					june: '06',
					july: '07',
					august: '08',
					september: '09',
					october: '10',
					november: '11',
					december: '12'
				};
				const month = monthMap[monthStr.toLowerCase()];
				if (month) {
					return `${year}-${month}-${day.padStart(2, '0')}`;
				}
			}

			return null;
		} catch {
			return null;
		}
	}

	/**
	 * Parse amount from string, handling currency symbols, commas, and parentheses for negatives
	 */
	protected parseAmount(amountStr: string): number | null {
		try {
			// Trim whitespace and any surrounding quote characters left over from
			// double-encoded CSV exports (e.g. EQ Bank emits `"""-$33.00"""` which
			// unwraps once to a value still containing literal " characters).
			amountStr = amountStr
				.trim()
				.replace(/^["']+|["']+$/g, '')
				.trim();

			// Check if amount is in parentheses (negative)
			const isNegative = amountStr.startsWith('(') && amountStr.endsWith(')');
			if (isNegative) {
				amountStr = amountStr.slice(1, -1);
			}

			// Remove currency symbols, commas, whitespace, and any embedded quotes
			amountStr = amountStr.replace(/[$,\s"']/g, '');

			// Parse the number
			const amount = parseFloat(amountStr);
			if (isNaN(amount)) return null;

			return isNegative ? -Math.abs(amount) : amount;
		} catch {
			return null;
		}
	}

	/**
	 * Remove BOM (Byte Order Mark) if present
	 */
	protected removeBOM(content: string): string {
		if (content.charCodeAt(0) === 0xfeff) {
			return content.slice(1);
		}
		return content;
	}

	/**
	 * Check if a header row contains expected columns (case-insensitive)
	 */
	protected hasExpectedColumns(header: string[], expectedColumns: string[]): boolean {
		const headerLower = header.map((h) => h.toLowerCase().trim());
		return expectedColumns.every((col) => headerLower.includes(col.toLowerCase()));
	}

	/**
	 * Normalizes transaction amounts to the app convention:
	 * negative = expense, positive = refund/credit.
	 *
	 * The per-bank sign convention comes from the `expensesArePositive` subclass
	 * property (RF-11):
	 * - PC Financial, EQ Bank, RBC, TD Bank, Simplii already use negative for
	 *   expenses → `expensesArePositive = false` (default), keep signs as-is
	 * - American Express uses positive for expenses → `expensesArePositive = true`,
	 *   invert the sign
	 *
	 * @param amount - The parsed amount from CSV
	 * @returns Normalized amount (negative = expense, positive = refund/credit) or null if input is null
	 *
	 * @example
	 * // PC Financial (expensesArePositive = false): -50.00 (expense) → keep as-is
	 * normalizeAmount(-50.00) // Returns -50.00
	 *
	 * @example
	 * // American Express (expensesArePositive = true): 50.00 (expense) → invert to -50.00
	 * normalizeAmount(50.00) // Returns -50.00
	 *
	 * @example
	 * // PC Financial (expensesArePositive = false): 25.00 (refund) → keep as-is
	 * normalizeAmount(25.00) // Returns 25.00
	 *
	 * Specification: #{#trn1b}
	 */
	protected normalizeAmount(amount: number | null): number | null {
		if (amount === null || amount === undefined) return null;
		if (amount === 0) return 0;

		return this.expensesArePositive ? amount * -1 : amount;
	}
}

