import type { ParsedTransaction } from '$lib/models/Transaction';

/**
 * Shape of the minimal existing-row data needed for dedup:
 * only the fields that participate in the match key.
 */
export interface ExistingTransactionRow {
	transaction_date: string;
	vendor_name: string;
	amount: number;
}

export interface ImportPlan {
	toInsert: ParsedTransaction[];
	skipped: number;
}

/**
 * Count-based duplicate detection for transaction imports.
 *
 * Specifications implemented:
 * - #{#tid1a} Count-based duplicate detection
 * - #{#tid2a} Dedup algorithm
 *
 * For each distinct match key `(transaction_date, vendor_name, amount)` in `fileRows`,
 * inserts `max(0, fileCount - dbCount)` rows. Rows beyond that threshold are counted
 * as skipped. Caller is responsible for scoping `existingRows` to the same
 * `(family_id, credit_card_type)` as the import (see #{#tid2b}) and for including
 * excluded rows so re-import doesn't resurrect them (see #{#tid5a}).
 */
export function computeImportPlan(
	fileRows: ParsedTransaction[],
	existingRows: ExistingTransactionRow[]
): ImportPlan {
	const keyOf = (r: { transaction_date: string; vendor_name: string; amount: number }) =>
		`${r.transaction_date}|${r.vendor_name}|${r.amount}`;

	const dbCounts = new Map<string, number>();
	for (const r of existingRows) {
		const k = keyOf(r);
		dbCounts.set(k, (dbCounts.get(k) ?? 0) + 1);
	}

	const fileGroups = new Map<string, ParsedTransaction[]>();
	for (const t of fileRows) {
		const k = keyOf(t);
		const group = fileGroups.get(k) ?? [];
		group.push(t);
		fileGroups.set(k, group);
	}

	const toInsert: ParsedTransaction[] = [];
	let skipped = 0;
	for (const [key, rows] of fileGroups) {
		const dbCount = dbCounts.get(key) ?? 0;
		const insertCount = Math.max(0, rows.length - dbCount);
		toInsert.push(...rows.slice(0, insertCount));
		skipped += rows.length - insertCount;
	}

	return { toInsert, skipped };
}

