import { describe, it, expect } from 'vitest';
import { parseExpenseImportCsv } from './expenseImportCsv';

/**
 * Pure parser for the historical-expense CSV import.
 *
 * Format (family's Excel/CSV export):
 *   Timestamp, Merchant, Amount, Category, Tag
 * where Amount is positive for a purchase and negative for a refund (same sign
 * convention as receipts.total_amount), Tag is ignored, and Category is a plain
 * name resolved to a category id later in the pipeline.
 */
describe('parseExpenseImportCsv', () => {
	const header = 'Timestamp,Merchant,Amount,Category,Tag';

	it('parses a well-formed row keeping the amount sign', () => {
		const csv = `${header}\n2025-01-02,Petro Canada,33.53,Gas,`;
		const { rows, errors } = parseExpenseImportCsv(csv);

		expect(errors).toEqual([]);
		expect(rows).toEqual([
			{
				transaction_date: '2025-01-02',
				merchant_name: 'Petro Canada',
				total_amount: 33.53,
				categoryName: 'Gas'
			}
		]);
	});

	it('keeps negative amounts (refunds) as negative — no inversion, no abs', () => {
		const csv = `${header}\n2025-01-06,Sporting Life,-394.35,Clothes,`;
		const { rows } = parseExpenseImportCsv(csv);
		expect(rows[0].total_amount).toBe(-394.35);
	});

	it('maps a blank Category to null (Uncategorized)', () => {
		const csv = `${header}\n2025-01-02,Some Shop,10.00,,`;
		const { rows } = parseExpenseImportCsv(csv);
		expect(rows[0].categoryName).toBeNull();
	});

	it('ignores the Tag column entirely', () => {
		const csv = `${header}\n2025-01-02,Amazon,22.59,Gifts,birthday`;
		const { rows } = parseExpenseImportCsv(csv);
		expect(rows[0]).not.toHaveProperty('tag');
		expect(rows[0].merchant_name).toBe('Amazon');
		expect(rows[0].categoryName).toBe('Gifts');
	});

	it('handles quoted fields containing commas', () => {
		const csv = `${header}\n2025-01-02,"Le Vieux St. Laurent, Bar",68.58,Travel - Food,`;
		const { rows } = parseExpenseImportCsv(csv);
		expect(rows[0].merchant_name).toBe('Le Vieux St. Laurent, Bar');
		expect(rows[0].categoryName).toBe('Travel - Food');
	});

	it('matches headers case-insensitively and in any order', () => {
		const csv = `category,AMOUNT,merchant,timestamp\nGroceries,15.99,Metro,2025-01-10`;
		const { rows, errors } = parseExpenseImportCsv(csv);
		expect(errors).toEqual([]);
		expect(rows[0]).toEqual({
			transaction_date: '2025-01-10',
			merchant_name: 'Metro',
			total_amount: 15.99,
			categoryName: 'Groceries'
		});
	});

	it('strips a UTF-8 BOM before reading the header', () => {
		const csv = `﻿${header}\n2025-01-03,Costco,188.53,Groceries,`;
		const { rows, errors } = parseExpenseImportCsv(csv);
		expect(errors).toEqual([]);
		expect(rows).toHaveLength(1);
	});

	it('reports missing required columns and returns no rows', () => {
		const csv = `Timestamp,Merchant,Notes\n2025-01-02,Petro,x`;
		const { rows, errors } = parseExpenseImportCsv(csv);
		expect(rows).toEqual([]);
		expect(errors.join(' ')).toMatch(/missing required column/i);
		expect(errors.join(' ')).toMatch(/amount/i);
		expect(errors.join(' ')).toMatch(/category/i);
	});

	it('reports an empty file', () => {
		const { rows, errors } = parseExpenseImportCsv('');
		expect(rows).toEqual([]);
		expect(errors.length).toBeGreaterThan(0);
	});

	it('skips a row with an unparseable date and reports its 1-based row number', () => {
		const csv = `${header}\n2025-01-02,Good,10,Gas,\nnot-a-date,Bad,20,Gas,`;
		const { rows, errors } = parseExpenseImportCsv(csv);
		expect(rows).toHaveLength(1);
		expect(rows[0].merchant_name).toBe('Good');
		expect(errors.join(' ')).toMatch(/row 3/i);
		expect(errors.join(' ')).toMatch(/date/i);
	});

	it('skips a row with a missing merchant name', () => {
		const csv = `${header}\n2025-01-02,,10,Gas,`;
		const { rows, errors } = parseExpenseImportCsv(csv);
		expect(rows).toEqual([]);
		expect(errors.join(' ')).toMatch(/merchant/i);
	});

	it('skips a row with an unparseable amount', () => {
		const csv = `${header}\n2025-01-02,Petro,abc,Gas,`;
		const { rows, errors } = parseExpenseImportCsv(csv);
		expect(rows).toEqual([]);
		expect(errors.join(' ')).toMatch(/amount/i);
	});

	it('accepts amounts with currency symbols and thousands separators', () => {
		const csv = `${header}\n2025-01-02,Reno,"$1,234.56",Home,`;
		const { rows } = parseExpenseImportCsv(csv);
		expect(rows[0].total_amount).toBe(1234.56);
	});

	it('parses many rows and collects one error per bad row without aborting', () => {
		const csv = [
			header,
			'2025-01-02,A,1,Gas,',
			'bad,B,2,Gas,',
			'2025-01-03,C,3,Gas,',
			'2025-01-04,,4,Gas,'
		].join('\n');
		const { rows, errors } = parseExpenseImportCsv(csv);
		expect(rows.map((r) => r.merchant_name)).toEqual(['A', 'C']);
		expect(errors).toHaveLength(2);
	});
});

