import { describe, it, expect } from 'vitest';
import { computeExpenseImportPlan } from './expenseImportPlan';
import type { ParsedExpenseImportRow } from './expenseImportCsv';

const row = (over: Partial<ParsedExpenseImportRow> = {}): ParsedExpenseImportRow => ({
	transaction_date: '2025-01-02',
	merchant_name: 'Petro Canada',
	total_amount: 33.53,
	categoryName: 'Gas',
	...over
});

describe('computeExpenseImportPlan', () => {
	it('inserts every row when there is no existing data', () => {
		const rows = [row(), row({ merchant_name: 'Metro', categoryName: 'Groceries' })];
		const plan = computeExpenseImportPlan(rows, [], ['Gas', 'Groceries']);
		expect(plan.toInsert).toHaveLength(2);
		expect(plan.duplicatesSkipped).toBe(0);
	});

	it('skips a row already present (same date, merchant, amount, category)', () => {
		const plan = computeExpenseImportPlan(
			[row()],
			[{ transaction_date: '2025-01-02', merchant_name: 'Petro Canada', total_amount: 33.53, categoryName: 'Gas' }],
			['Gas']
		);
		expect(plan.toInsert).toEqual([]);
		expect(plan.duplicatesSkipped).toBe(1);
	});

	it('count-based: two identical file rows, one already in db → insert one, skip one', () => {
		const plan = computeExpenseImportPlan(
			[row(), row()],
			[{ transaction_date: '2025-01-02', merchant_name: 'Petro Canada', total_amount: 33.53, categoryName: 'Gas' }],
			['Gas']
		);
		expect(plan.toInsert).toHaveLength(1);
		expect(plan.duplicatesSkipped).toBe(1);
	});

	it('does not treat a different amount as a duplicate', () => {
		const plan = computeExpenseImportPlan(
			[row({ total_amount: 40 })],
			[{ transaction_date: '2025-01-02', merchant_name: 'Petro Canada', total_amount: 33.53, categoryName: 'Gas' }],
			['Gas']
		);
		expect(plan.toInsert).toHaveLength(1);
		expect(plan.duplicatesSkipped).toBe(0);
	});

	it('does not treat a different category as a duplicate', () => {
		const plan = computeExpenseImportPlan(
			[row({ categoryName: 'Car - Gas' })],
			[{ transaction_date: '2025-01-02', merchant_name: 'Petro Canada', total_amount: 33.53, categoryName: 'Gas' }],
			['Gas', 'Car - Gas']
		);
		expect(plan.toInsert).toHaveLength(1);
	});

	it('matches an existing receipt with a null category against a file row with null category', () => {
		const plan = computeExpenseImportPlan(
			[row({ categoryName: null })],
			[{ transaction_date: '2025-01-02', merchant_name: 'Petro Canada', total_amount: 33.53, categoryName: null }],
			[]
		);
		expect(plan.duplicatesSkipped).toBe(1);
	});

	it('lists distinct new category names not already present (case-insensitive)', () => {
		const rows = [
			row({ categoryName: 'Gas' }),
			row({ categoryName: 'Coffee and Tea' }),
			row({ categoryName: 'coffee and tea' }), // dup of the above, different case
			row({ categoryName: 'Sports and Fitness' })
		];
		const plan = computeExpenseImportPlan(rows, [], ['gas']); // Gas already exists (different case)
		expect(plan.newCategoryNames).toEqual(['Coffee and Tea', 'Sports and Fitness']);
	});

	it('excludes null (Uncategorized) rows from newCategoryNames', () => {
		const plan = computeExpenseImportPlan([row({ categoryName: null })], [], []);
		expect(plan.newCategoryNames).toEqual([]);
	});

	it('only counts categories from rows that will actually be inserted', () => {
		// The only row referencing "Brand New" is a duplicate → nothing new to create.
		const dup = row({ categoryName: 'Brand New' });
		const plan = computeExpenseImportPlan(
			[dup],
			[{ transaction_date: dup.transaction_date, merchant_name: dup.merchant_name, total_amount: dup.total_amount, categoryName: 'Brand New' }],
			['Brand New']
		);
		expect(plan.toInsert).toEqual([]);
		expect(plan.newCategoryNames).toEqual([]);
	});
});

