import { describe, it, expect } from 'vitest';
import type { SupabaseClient } from '@supabase/supabase-js';
import { ExpenseImportService } from './ExpenseImportService';

/**
 * A purpose-built Supabase fake for the multi-table import flow.
 *
 * The shared chainable mock uses one stub per client and so can't return
 * categories for a `categories` select while returning inserted ids for a
 * `receipts` insert in the same flow. This fake dispatches by (table, op) and
 * records what was written so the spec can assert receipts, created categories,
 * and expense_categories links independently.
 */
interface FakeState {
	categories: { id: string; name: string; family_id: string }[];
	existingReceipts: unknown[];
	insertedReceipts: Record<string, unknown>[];
	insertedLinks: Record<string, unknown>[];
	createdCategoryNames: string[];
}

function createFake(initial: Partial<FakeState> = {}): {
	client: SupabaseClient;
	state: FakeState;
} {
	const state: FakeState = {
		categories: initial.categories ?? [],
		existingReceipts: initial.existingReceipts ?? [],
		insertedReceipts: [],
		insertedLinks: [],
		createdCategoryNames: []
	};
	let receiptCounter = 0;

	function builder(table: string) {
		let op: 'select' | 'insert' | 'upsert' = 'select';
		let payload: unknown = null;

		const resolveValue = (): { data: unknown; error: null } => {
			if (table === 'categories' && op === 'select') {
				return { data: state.categories.slice(), error: null };
			}
			if (table === 'receipts' && op === 'select') {
