1	/**
2	 * ExpenseImportService
3	 *
4	 * Imports historical Expenses from a CSV/XLS/XLSX file. Because Expenses are
5	 * computed (receipts + expense_categories + categories), each file row becomes:
6	 *   - a `receipts` row (imageless: `receipt_image_path` NULL, `suspicious_date`
7	 *     false — these are intentional old entries), created the same way as a
8	 *     manual receipt, and
9	 *   - an `expense_categories` link to a category resolved (or created) by name.
10	 *
11	 * This service is the imperative shell around three pure functions
12	 * (`parseExpenseImportCsv`, `computeExpenseImportPlan`, `buildExpenseCategoryLinks`)
13	 * — it reads the file, talks to Supabase, and lets the pure core do the logic.
14	 * A two-step flow (`buildPreview` → `commit`) lets the page show a confirmation
15	 * before writing. Design: docs/plans/2026-07-09-spending-report-design.md
16	 */
17	
18	import type { SupabaseClient } from '@supabase/supabase-js';
19	import { convertExcelToCSV, isExcelFile } from './ExcelToCSVConverter';
20	import { CategoryService } from './CategoryService';
21	import { parseExpenseImportCsv, type ParsedExpenseImportRow } from '$lib/utils/expenseImportCsv';
22	import {
23		computeExpenseImportPlan,
24		buildExpenseCategoryLinks,
25		type ExistingReceiptForDedup
26	} from '$lib/utils/expenseImportPlan';
27	
28	/** Everything the confirmation UI needs, plus the exact rows to commit. */
29	export interface ExpenseImportPreview {
30		/** Per-row parse problems (bad date/amount/merchant); those rows are dropped. */
31		parseErrors: string[];
32		/** How many rows parsed cleanly (before dedup). */
33		totalParsed: number;
34		/** Rows that will actually be created (duplicates already removed). */
35		toInsert: ParsedExpenseImportRow[];
36		/** Count of rows skipped because an identical expense already exists. */
37		duplicatesSkipped: number;
38		/** Category names that don't exist yet and will be created (Uncategorized). */
39		newCategoryNames: string[];
40	}
41	
42	export interface ExpenseImportResult {
43		imported: number;
44		categoriesCreated: number;
45	}
46	
47	/** Chunk size for batch inserts, to keep request payloads bounded. */
48	const INSERT_CHUNK = 500;
49	
50	interface ReceiptDedupEmbed {
51		transaction_date: string | null;
52		merchant_name: string | null;
53		total_amount: number | null;
54		expense_categories: { categories: { name: string | null } | null } | null;
55	}
56	
57	export class ExpenseImportService {
58		private supabase: SupabaseClient;
59		private categoryService: CategoryService;
60	
61		constructor(supabase: SupabaseClient) {
62			this.supabase = supabase;
63			this.categoryService = new CategoryService(supabase);
64		}
65	
66		/** Read a CSV/XLS/XLSX File into CSV text (Excel is converted first). */
67		async readCsvText(file: File): Promise<string> {
68			return new Promise((resolve, reject) => {
69				const reader = new FileReader();
70				reader.onload = (e) => {
71					try {
72						if (isExcelFile(file)) {
73							resolve(convertExcelToCSV(e.target?.result as ArrayBuffer));
74						} else {
75							resolve((e.target?.result as string) ?? '');
76						}
77					} catch (err) {
78						reject(err instanceof Error ? err : new Error('Failed to read file'));
79					}
80				};
81				reader.onerror = () => reject(new Error('Failed to read file'));
82				if (isExcelFile(file)) {
83					reader.readAsArrayBuffer(file);
84				} else {
85					reader.readAsText(file);
86				}
87			});
88		}
89	
90		/**
91		 * Parse the file and compute what an import would do, without writing
92		 * anything. Loads the family's categories and the receipts already recorded
93		 * in the file's date range so dedup and the new-category warning are accurate.
94		 */
95		async buildPreview(familyId: string, file: File): Promise<ExpenseImportPreview> {
96			const text = await this.readCsvText(file);
97			return this.previewFromText(familyId, text);
98		}
99	
100		/** The DB + pure-logic half of {@link buildPreview}, split out so it can be
101		 * exercised without a browser `FileReader`. */
102		async previewFromText(familyId: string, text: string): Promise<ExpenseImportPreview> {
103			const { rows, errors } = parseExpenseImportCsv(text);
104	
105			const categories = await this.categoryService.getFamilyCategories(familyId);
106			const existing = rows.length > 0 ? await this.loadExistingReceipts(rows) : [];
107			const plan = computeExpenseImportPlan(
108				rows,
109				existing,
110				categories.map((c) => c.name)
111			);
112	
113			return {
114				parseErrors: errors,
115				totalParsed: rows.length,
116				toInsert: plan.toInsert,
117				duplicatesSkipped: plan.duplicatesSkipped,
118				newCategoryNames: plan.newCategoryNames
119			};
120		}
121	
122		/**
123		 * Create the receipts and their category links for the previewed rows.
124		 * Resolves (creating as needed) every category, inserts the receipts in order,
125		 * then links each receipt to its category. Returns counts for the summary.
126		 */
127		async commit(familyId: string, toInsert: ParsedExpenseImportRow[]): Promise<ExpenseImportResult> {
128			if (toInsert.length === 0) {
129				return { imported: 0, categoriesCreated: 0 };
130			}
131	
132			const { map, created } = await this.resolveCategoryIds(familyId, toInsert);
133			const insertedIds = await this.insertReceipts(toInsert);
134			const links = buildExpenseCategoryLinks(insertedIds, toInsert, map);
135			await this.insertExpenseCategories(links);
136	
137			return { imported: insertedIds.length, categoriesCreated: created };
138		}
139	
140		/** Load existing receipts in the file's date range, flattened for dedup. */
141		private async loadExistingReceipts(
142			rows: ParsedExpenseImportRow[]
143		): Promise<ExistingReceiptForDedup[]> {
144			const dates = rows.map((r) => r.transaction_date).sort();
145			const minDate = dates[0];
146			const maxDate = dates[dates.length - 1];
147	
148			const { data, error } = await this.supabase
149				.from('receipts')
150				.select(
151					`transaction_date, merchant_name, total_amount, expense_categories ( categories ( name ) )`
152				)
153				.gte('transaction_date', minDate)
154				.lte('transaction_date', maxDate);
155	
156			if (error) throw new Error(error.message);
157	
158			const receipts = (data ?? []) as unknown as ReceiptDedupEmbed[];
159			return receipts.map((r) => ({
160				transaction_date: r.transaction_date,
161				merchant_name: r.merchant_name,
162				total_amount: r.total_amount,
163				categoryName: r.expense_categories?.categories?.name ?? null
164			}));
165		}
166	
167		/**
168		 * Build a lowercased-name → id map for every category the rows reference,
169		 * creating the ones that don't exist yet. Returns the map and how many were
170		 * created.
171		 */
172		private async resolveCategoryIds(
173			familyId: string,
174			toInsert: ParsedExpenseImportRow[]
175		): Promise<{ map: Map<string, string>; created: number }> {
176			const categories = await this.categoryService.getFamilyCategories(familyId);
177			const map = new Map<string, string>(categories.map((c) => [c.name.trim().toLowerCase(), c.id]));
178	
179			const needed = new Map<string, string>(); // lowercased -> original casing
180			for (const r of toInsert) {
181				if (r.categoryName === null) continue;
182				const lower = r.categoryName.trim().toLowerCase();
183				if (!map.has(lower)) needed.set(lower, r.categoryName.trim());
184			}
185	
186			let created = 0;
187			for (const [lower, name] of needed) {
188				try {
189					const category = await this.categoryService.createCategory(familyId, name);
190					map.set(lower, category.id);
191					created++;
192				} catch (e) {
193					// A concurrent create (or a name that already existed under different
194					// casing) is fine — re-fetch and resolve the id instead of failing.
195					const fresh = await this.categoryService.getFamilyCategories(familyId);
196					const found = fresh.find((c) => c.name.trim().toLowerCase() === lower);
197					if (!found) throw e;
198					map.set(lower, found.id);
199				}
200			}
201	
202			return { map, created };
203		}
204	

