1	import { describe, it, expect } from 'vitest';
2	import type { SupabaseClient } from '@supabase/supabase-js';
3	import { ExpenseImportService } from './ExpenseImportService';
4	
5	/**
6	 * A purpose-built Supabase fake for the multi-table import flow.
7	 *
8	 * The shared chainable mock uses one stub per client and so can't return
9	 * categories for a `categories` select while returning inserted ids for a
10	 * `receipts` insert in the same flow. This fake dispatches by (table, op) and
11	 * records what was written so the spec can assert receipts, created categories,
12	 * and expense_categories links independently.
13	 */
14	interface FakeState {
15		categories: { id: string; name: string; family_id: string }[];
16		existingReceipts: unknown[];
17		insertedReceipts: Record<string, unknown>[];
18		insertedLinks: Record<string, unknown>[];
19		createdCategoryNames: string[];
20	}
21	
22	function createFake(initial: Partial<FakeState> = {}): {
23		client: SupabaseClient;
24		state: FakeState;
25	} {
26		const state: FakeState = {
27			categories: initial.categories ?? [],
28			existingReceipts: initial.existingReceipts ?? [],
29			insertedReceipts: [],
30			insertedLinks: [],
31			createdCategoryNames: []
32		};
33		let receiptCounter = 0;
34	
35		function builder(table: string) {
36			let op: 'select' | 'insert' | 'upsert' = 'select';
37			let payload: unknown = null;
38	
39			const resolveValue = (): { data: unknown; error: null } => {
40				if (table === 'categories' && op === 'select') {
41					return { data: state.categories.slice(), error: null };
42				}
43				if (table === 'receipts' && op === 'select') {
44					return { data: state.existingReceipts, error: null };
45				}
46				if (table === 'receipts' && op === 'insert') {
47					const rows = (payload as Record<string, unknown>[]).map((r) => {
48						const stored = { id: `r${receiptCounter++}`, ...r };
49						state.insertedReceipts.push(stored);
50						return { id: stored.id };
51					});
52					return { data: rows, error: null };
53				}
54				if (table === 'expense_categories' && op === 'upsert') {
55					state.insertedLinks.push(...(payload as Record<string, unknown>[]));
56					return { data: null, error: null };
57				}
58				return { data: null, error: null };
59			};
60	
61			const b: Record<string, unknown> = {
62				select: () => b,
63				eq: () => b,
64				gte: () => b,
65				lte: () => b,
66				order: () => b,
67				insert: (p: unknown) => {
68					op = 'insert';
69					payload = p;
70					return b;
71				},
72				upsert: (p: unknown) => {
73					op = 'upsert';
74					payload = p;
75					return Promise.resolve(resolveValue());
76				},
77				single: () => {
