import { describe, it, expect } from 'vitest';
import { parseYearParam } from './spendingYear';

const params = (query: string) => new URLSearchParams(query);

describe('parseYearParam', () => {
	it('reads a valid year from the URL', () => {
		expect(parseYearParam(params('year=2025'), 2026)).toBe(2025);
	});

	it('falls back to the current year when the param is absent', () => {
		expect(parseYearParam(params(''), 2026)).toBe(2026);
	});

	it('falls back when the param is not a number', () => {
		expect(parseYearParam(params('year=abc'), 2026)).toBe(2026);
	});

	it('falls back for an out-of-range (absurd) year', () => {
		expect(parseYearParam(params('year=99999'), 2026)).toBe(2026);
		expect(parseYearParam(params('year=0'), 2026)).toBe(2026);
	});

	it('parses a leading-numeric value via parseInt (trailing junk ignored)', () => {
		expect(parseYearParam(params('year=2025x'), 2026)).toBe(2025);
	});

	it('accepts the range boundaries', () => {
		expect(parseYearParam(params('year=1900'), 2026)).toBe(1900);
		expect(parseYearParam(params('year=2999'), 2026)).toBe(2999);
	});
});

