import SpendingChart from '$lib/components/SpendingChart.svelte';
import type { Session } from '@supabase/supabase-js';

let session: Session | null = $state(null);
let familyId: string | null = $state(null);
let year = $state(new Date().getFullYear());
let view = $state<'table' | 'chart'>('table');
let loading = $state(true);
let error: string | null = $state(null);
let report = $state<SpendingReport | null>(null);
// Kept in state (not just local to loadReport) so cell drill-down can expand a
// Grouping/Importance to its member category ids.
let categories = $state<SpendingCategory[]>([]);
let groups = $state<CategoryGroup[]>([]);

onMount(async () => {
	const { data } = await supabase.auth.getSession();
	session = data.session;
	if (!session) return;

	familyId = await getDefaultFamilyId();
	if (!familyId) {
		error = 'No family found. Please contact support.';
		loading = false;
		return;
	}

	// Restore the year from the URL so a refresh / round-trip keeps the
	// selection instead of snapping back to the current year.
	year = parseYearParam($page.url.searchParams, new Date().getFullYear());
	await loadReport();
});

async function loadReport() {
	if (!session?.user || !familyId) return;

	try {
		loading = true;
		error = null;

		const categoryService = new CategoryService(supabase);
		const expenseService = new ExpenseService(supabase);

		// Seed the default hierarchy the first time a family opens the report
		// (idempotent server-side), mirroring how categories self-initialize.
		let importanceAreas = await categoryService.getFamilyImportanceAreas(familyId);
		if (importanceAreas.length === 0) {
			await categoryService.createDefaultHierarchy(familyId);
			importanceAreas = await categoryService.getFamilyImportanceAreas(familyId);
		}

		const [loadedGroups, loadedCategories, expenses] = await Promise.all([
			categoryService.getFamilyGroups(familyId),
			categoryService.getFamilyCategories(familyId),
			expenseService.getExpenses(session.user.id, {
				startDate: `${year}-01-01`,
				endDate: `${year}-12-31`
			})
		]);

		groups = loadedGroups;
		categories = loadedCategories;
		report = buildSpendingReport(expenses, loadedCategories, loadedGroups, importanceAreas, year);
	} catch (err) {
		console.error('Error loading spending report:', err);
		error = err instanceof Error ? err.message : 'Failed to load the spending report';
	} finally {
		loading = false;
	}
}

function changeYear(delta: number) {
	year += delta;
	// Persist the selection in the URL (no navigation, no remount) so a refresh
	// or a round-trip to another tab keeps this year.
	replaceState(resolve(`/spending?year=${year}`), {});
	loadReport();
}

/** A cell renders blank when no receipts fell in it, otherwise the amount. */

