import { onMount } from 'svelte';
import { resolve } from '$app/paths';
import { page } from '$app/state';
import { replaceState } from '$app/navigation';
import { supabase } from '$lib/supabaseClient';
import { ExpenseService } from '$lib/services/ExpenseService';
import { CategoryService } from '$lib/services/CategoryService';
import { getDefaultFamilyId } from '$lib/utils/familyUtils';
import { formatCurrency } from '$lib/utils/formatCurrency';
import {
	buildSpendingReport,
	type SpendingReport,
	type SpendingCategory,
	type Cell,
	type ReportRow
} from '$lib/utils/spendingReport';
import {
	buildSpendingDrilldownParams,
	type DrilldownScope,
	type DrilldownColumn
} from '$lib/utils/spendingDrilldown';
import type { CategoryGroup } from '$lib/types/Hierarchy';
import { parseYearParam } from '$lib/utils/spendingYear';
import SpendingChart from '$lib/components/SpendingChart.svelte';
import type { Session } from '@supabase/supabase-js';

let session: Session | null = $state(null);
let familyId: string | null = $state(null);
const currentYear = new Date().getFullYear();
// The URL is the source of truth for the selected year, so it survives a
// refresh and navigating away and back. `page` comes from `$app/state` (the
// Svelte 5 reactive object), NOT the legacy `$app/stores` `$page` store — the
// store doesn't reliably re-track inside `$derived` across a remount (e.g.
// Back from a drill-down landed here with a stale year). Deriving off the
// reactive `page.url` keeps `year` in lock-step with `?year=`.
let year = $derived(parseYearParam(page.url.searchParams, currentYear));
let view = $state<'table' | 'chart'>('table');
let loading = $state(true);
let error: string | null = $state(null);
let report = $state<SpendingReport | null>(null);
// Kept in state (not just local to loadReport) so cell drill-down can expand a
// Grouping/Importance to its member category ids.
let categories = $state<SpendingCategory[]>([]);
let groups = $state<CategoryGroup[]>([]);

onMount(async () => {
	const { data } = await supabase.auth.getSession();
	session = data.session;
	if (!session) {
		loading = false;
		return;
	}

	familyId = await getDefaultFamilyId();
	if (!familyId) {
		error = 'No family found. Please contact support.';
		loading = false;
	}
});

// Load (or reload) whenever the resolved family or the URL year changes. The
// URL is the source of truth for `year`, so a refresh / back-navigation to a
// past year reloads that year rather than the current one.
$effect(() => {
	const reportYear = year; // track the derived year
	if (session?.user && familyId) {
		loadReport(reportYear);
	}
});

async function loadReport(reportYear: number) {
	if (!session?.user || !familyId) return;

	try {
		loading = true;
		error = null;

		const categoryService = new CategoryService(supabase);
		const expenseService = new ExpenseService(supabase);

		// Seed the default hierarchy the first time a family opens the report
		// (idempotent server-side), mirroring how categories self-initialize.
		let importanceAreas = await categoryService.getFamilyImportanceAreas(familyId);
		if (importanceAreas.length === 0) {
			await categoryService.createDefaultHierarchy(familyId);
			importanceAreas = await categoryService.getFamilyImportanceAreas(familyId);
		}

		const [loadedGroups, loadedCategories, expenses] = await Promise.all([
			categoryService.getFamilyGroups(familyId),
			categoryService.getFamilyCategories(familyId),
			expenseService.getExpenses(session.user.id, {
				startDate: `${reportYear}-01-01`,
				endDate: `${reportYear}-12-31`
			})
		]);

		groups = loadedGroups;
		categories = loadedCategories;
		report = buildSpendingReport(
			expenses,
			loadedCategories,
			loadedGroups,
			importanceAreas,
			reportYear
		);
	} catch (err) {
		console.error('Error loading spending report:', err);
		error = err instanceof Error ? err.message : 'Failed to load the spending report';
	} finally {
		loading = false;
	}
}

function changeYear(delta: number) {
	// Write the new year to the URL; the derived `year` and the reload effect
	// follow. No manual reload here — the URL drives everything.
	replaceState(resolve(`/spending?year=${year + delta}`), {});
}

/** A cell renders blank when no receipts fell in it, otherwise the amount. */
function cellText(cell: Cell): string {
	return cell.count === 0 ? '' : formatCurrency(cell.amount);
}

